// SecureMessage/src/components/ViewSendMessages.jsx
import React, { useState } from "react";
import "./CSS/ViewSendMessages.css";
import { IoArrowBack } from "react-icons/io5";
import { IoIosSend } from "react-icons/io";
import { MdAttachFile } from "react-icons/md";

function ViewSendMessages({ user, onBack }) {
  const [receiver, setReceiver] = useState("");
  const [message, setMessage] = useState("");
  const [status, setStatus] = useState("");
  const [chat, setChat] = useState([]);

  const handleSendMessage = async () => {
    if (!receiver.trim() || !message.trim()) {
      setStatus("Receiver and message are required.");
      return;
    }

    try {
      const response = await fetch("http://127.0.0.1:5000/send-message", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          sender: user.email,
          receiver,
          message,
        }),
      });

      const result = await response.json();
      if (result.success) {
        const newMessage = {
          from: user.email,
          to: receiver,
          content: message,
          time: new Date().toLocaleTimeString(),
        };
        setChat([...chat, newMessage]);
        setMessage("");
        setReceiver("");
        setStatus("Message sent.");
      } else {
        setStatus("Failed to send message.");
      }
    } catch (err) {
      console.error(err);
      setStatus("Server error.");
    }
  };

  return (
    <div className="vsm-container">
      <header className="vsm-header">
        <button className="vsm-back" onClick={onBack}>
          <IoArrowBack size={24} />
        </button>
        <div className="vsm-user">
          <p className="vsm-name">{user.name}</p>
          <p className="vsm-email">{user.email}</p>
        </div>
      </header>

      <div className="vsm-chat-area">
        {chat.length === 0 ? (
          <p className="vsm-placeholder">No messages yet.</p>
        ) : (
          chat.map((msg, idx) => (
            <div
              key={idx}
              className={`vsm-message ${
                msg.from === user.email ? "vsm-sent" : "vsm-received"
              }`}
            >
              <div className="vsm-bubble">
                <p className="vsm-text">{msg.content}</p>
                <p className="vsm-time">{msg.time}</p>
              </div>
            </div>
          ))
        )}
      </div>

      <footer className="vsm-footer">
        <button className="vsm-attach">
          <MdAttachFile size={20} />
        </button>
        <input
          type="text"
          className="vsm-receiver"
          placeholder="Receiver Email"
          value={receiver}
          onChange={(e) => setReceiver(e.target.value)}
        />
        <input
          type="text"
          className="vsm-input"
          placeholder="Type your message..."
          value={message}
          onChange={(e) => setMessage(e.target.value)}
        />
        <button className="vsm-send" onClick={handleSendMessage}>
          <IoIosSend size={22} />
        </button>
      </footer>
    </div>
  );
}

export default ViewSendMessages;
